async def login_for_access_token(form_data: OAuth2PasswordRequestForm = Depends()) -> Token:
  user = await authenticate_user(form_data.username, form_data.password)
  if not user: raise HTTPException(401, "Incorrect email or password")
  access_token_expires = timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
  access_token = create_access_token(data={"user": user.email}, expires_delta=access_token_expires)
  return Token(access_token=access_token, token_type="bearer", user_id=user.id)

