async def update_user_details(user_id, user_to_update, user_public=Depends(user_authenticated)):
  if user_public.id != user_id: raise HTTPException(401, "Can't change details of this user")
  await update_user(user_public.id, user_to_update)
  user_updated = await get_user_by_id(user_id)
  return UserPublicResponse(data=assert_some(user_updated))

async def put_user_password(user_id, user_to_update, user_public=Depends(user_authenticated)):
  if user_public.id != user_id: raise HTTPException(401, "Can't change details of this user")
  await update_user_password(user_public.id, hash_password(user_to_update.password))
  return SuccessResponse()

